{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C35"],
      "claim": "Isoniazid absolute oral bioavailability was 93% in fasting adult TB patients, well above the 20% threshold."
    },
    {
      "card_ids": ["C14"],
      "claim": "Bromfenac absolute oral bioavailability was 67% ± 20% in healthy fasting subjects, supporting high bioavailability."
    },
    {
      "card_ids": ["C05"],
      "claim": "Nilotinib absolute bioavailability was 17% in patients, below the 20% threshold, but other nilotinib records report about 30%, making this molecule mixed."
    }
  ],
  "confidence": "moderate",
  "contradictory_card_ids": ["C05"],
  "decision_summary": "Most transferred absolute bioavailability records are well above 20%, including isoniazid 93% and bromfenac 67%; nilotinib is mixed with one 17% value but another 31% value, so the overall balance supports high bioavailability.",
  "evidence_gaps": [
    "Nilotinib has conflicting absolute bioavailability values (17% vs 31%), creating uncertainty.",
    "Molecule 7 provides only relative systemic availability, not an absolute F value.",
    "Molecules 9 and 10 report qualitative high bioavailability without numeric F values."
  ],
  "new_evidence_assessment": [],
  "prediction_basis_card_ids": ["C35", "C14"],
  "revision_action": "initial",
  "supportive_card_ids": ["C35", "C14"]
}

